// Nœud Code — "Données Mobidesk (CSV intégré)" : remplace Google Sheets en mode simulé.
// Collez ici un autre export CSV (même en-tête) pour tester vos propres données.
const csv = `date,commande,commercial,region,categorie,produit,quantite,prix_unitaire_ht,montant_ht
2026-01-06,C-1001,Aïcha Benali,Île-de-France,Mobilier,Bureau Oslo,4,349.00,1396.00
