2026-05-12,C-1018,Léa Martin,Nouvelle-Aquitaine,Rangement,Caisson Nova,8,129.00,1032.00
2026-05-19,C-1019,Aïcha Benali,Île-de-France,Mobilier,Fauteuil Ergo+,12,289.00,3468.00
2026-05-26,C-1020,Thomas Roussel,Auvergne-Rhône-Alpes,Éclairage,Lampe Halo,15,59.90,898.50
2026-06-02,C-1021,Léa Martin,Nouvelle-Aquitaine,Mobilier,Bureau Oslo,9,349.00,3141.00
2026-06-09,C-1022,Aïcha Benali,Île-de-France,Consommables,Pack papeterie,80,18.50,1480.00
2026-06-16,C-1023,Thomas Roussel,Auvergne-Rhône-Alpes,Mobilier,Bureau Oslo,7,349.00,2443.00
2026-06-23,C-1024,Léa Martin,Nouvelle-Aquitaine,Éclairage,Lampe Halo,18,59.90,1078.20`;
const [entete, ...lignes] = csv.trim().split("\n");
const colonnes = entete.split(",");
// Les valeurs restent des chaînes, comme ce que renvoie souvent Google Sheets : le nœud KPI les convertit.
return lignes.map(l => {
  const v = l.split(",");
  return { json: Object.fromEntries(colonnes.map((c, i) => [c, v[i]])) };
});

// Nœud Code — "Calcul des KPI de la semaine" (mode Run Once for All Items)
// Entrée : un item par ligne de la feuille ventes (colonnes du CSV Mobidesk)
// Sortie : un item { kpi: {...} } — tous les chiffres sont calculés ICI, jamais par le LLM.
// Différence avec la leçon L058 : la date de référence vient du nœud "Paramètres" (et non de $env,
// souvent bloqué par N8N_BLOCK_ENV_ACCESS_IN_NODE), et les montants sont aussi fournis déjà formatés.

// Toutes les dates sont manipulées en UTC à minuit pour éviter les décalages de fuseau.
const jour = s => new Date(String(s).slice(0, 10) + "T00:00:00Z");
const ref = $('Paramètres').first().json.date_ref;
const DATE_REF = jour(ref || new Date().toISOString());        // ex. "2026-06-29" pour tester
const lundi = new Date(DATE_REF);
lundi.setUTCDate(lundi.getUTCDate() - ((lundi.getUTCDay() + 6) % 7)); // lundi de la semaine en cours
const debutN = new Date(lundi); debutN.setUTCDate(debutN.getUTCDate() - 7);    // lundi précédent
const debutN1 = new Date(lundi); debutN1.setUTCDate(debutN1.getUTCDate() - 14);

const lignes = $input.all().map(i => i.json);
const num = v => Number(String(v).replace(/\s/g, "").replace(",", "."));   // "1 078,20" → 1078.2
const dans = (l, d1, d2) => { const d = jour(l.date); return d >= d1 && d < d2; };

const semN  = lignes.filter(l => dans(l, debutN, lundi));
const semN1 = lignes.filter(l => dans(l, debutN1, debutN));
const somme = arr => Math.round(arr.reduce((s, l) => s + num(l.montant_ht), 0) * 100) / 100;
const parCle = (arr, cle) => {
  const m = {};
  for (const l of arr) m[l[cle]] = (m[l[cle]] || 0) + num(l.montant_ht);
  return Object.entries(m).sort((a, b) => b[1] - a[1]).map(([k, v]) => ({ nom: k, ca: Math.round(v * 100) / 100 }));
};

const caN = somme(semN), caN1 = somme(semN1);
const variation = caN1 === 0 ? null : Math.round((caN - caN1) / caN1 * 1000) / 10;
const avoirs = semN.filter(l => num(l.quantite) < 0).length;
const fmt = d => d.toISOString().slice(0, 10);

// Formatage français fait par le CODE (le modèle recopie des chaînes prêtes) : « 1 078,20 € », « −55,9 % »
const euros = x => (x < 0 ? "-" : "") + Math.abs(x).toFixed(2).replace(".", ",").replace(/\B(?=(\d{3})+(?!\d))/g, " ") + " €";
const pct = v => v === null ? null : (v < 0 ? "−" : "+") + Math.abs(v).toFixed(1).replace(".", ",") + " %";
const cumul = somme(lignes);
const topCom = parCle(semN, "commercial"), topProd = parCle(semN, "produit");

return [{ json: { kpi: {
  periode: { debut: fmt(debutN), fin: fmt(new Date(lundi - 1)) },
  nb_lignes_semaine: semN.length,
  ca_semaine: caN,
  ca_semaine_precedente: caN1,
  variation_pct: variation,            // null si pas de référence
  cumul_semestre: cumul,               // toutes les lignes de la feuille
  avoirs_semaine: avoirs,
  top_commerciaux: topCom,
  top_produits: topProd,
  affichage: {                         // les mêmes chiffres, formatés pour être recopiés tels quels
    ca_semaine: euros(caN),
    ca_semaine_precedente: euros(caN1),
    variation_pct: pct(variation),
    cumul_semestre: euros(cumul),
    top_commerciaux: topCom.map(t => ({ nom: t.nom, ca: euros(t.ca) })),
    top_produits: topProd.map(t => ({ nom: t.nom, ca: euros(t.ca) })),
  },
  alerte: semN.length === 0 ? "Aucune ligne cette semaine : vérifier la source" : null
} } }];

// Nœud Code — "Rédaction simulée (sans clé)" : remplace la Basic LLM Chain en mode simulé.
// Rédige à partir de kpi.affichage, comme un modèle obéissant. Paramètres.panne permet de simuler
// une erreur typique d'un vrai modèle pour vérifier que le contrôle l'attrape :
//   ""              → texte fidèle            "faute_de_frappe" → 1 078,20 devient 1 087,20
//   "arrondi"       → « environ 1 100 € »     "invente"         → montant absent du JSON
const k = $input.first().json.kpi;
const panne = $('Paramètres').first().json.panne || "";
if (k.alerte) return [{ json: { text: `Rapport non généré : ${k.alerte}` } }];

const a = k.affichage;
let ca = a.ca_semaine;
if (panne === "faute_de_frappe") ca = ca.replace(/(\d)(\d),/, "$2$1,");
if (panne === "arrondi") ca = "environ " + String(Math.round(k.ca_semaine / 100) * 100).replace(/\B(?=(\d{3})+(?!\d))/g, " ") + " €";
const comparaison = a.variation_pct ? `(${a.variation_pct})` : "(pas de semaine de référence)";
let attention = k.avoirs_semaine > 0 ? `${k.avoirs_semaine} avoir(s) cette semaine.` : "aucun avoir cette semaine.";
if (k.ca_semaine < 0) attention += " Chiffre d'affaires de la semaine négatif.";
const lignes = [
  `Objet : Mobidesk — ventes semaine du ${k.periode.debut} au ${k.periode.fin}`,
  `1. Chiffre de la semaine : CA ${ca}, contre ${a.ca_semaine_precedente} la semaine précédente ${comparaison}. Cumul du semestre : ${a.cumul_semestre}.`,
  `2. Faits marquants : ${a.top_commerciaux[0].nom} en tête (${a.top_commerciaux[0].ca}) ; produit en tête : ${a.top_produits[0].nom} (${a.top_produits[0].ca}).`,
  `3. Points d'attention : ${attention}`,
];
if (panne === "invente") lignes.push("Objectif mensuel atteint à 4 250,00 €.");
return [{ json: { text: lignes.join("\n") } }];

// Nœud Code — "Contrôle des chiffres du rapport" (mode Run Once for All Items)
// Vérifie que chaque nombre du texte rédigé existe dans le JSON kpi ; sinon, avertissement + relecture humaine.
// Différence avec la leçon L058 (section 5) : les numéros de section en début de ligne (« 1. », « 2. », « 3. »)
// sont retirés avant l'analyse ; sans cela, le format imposé par le prompt déclenche de fausses alertes.
const entree = $input.first().json;
const texte = entree.text ?? entree.output ?? "";       // sortie de la Basic LLM Chain
const kpi = $('Calcul des KPI de la semaine').first().json.kpi;

// Tous les nombres autorisés : valeurs du JSON (en valeur absolue, arrondies à 2 décimales)
const autorises = new Set();
const collecter = v => {
  if (typeof v === "number") autorises.add(Math.abs(Math.round(v * 100) / 100));
  else if (v && typeof v === "object") Object.values(v).forEach(collecter);
};
collecter(kpi);

// Nombres trouvés dans le texte (formats « 1 078,20 », « 55,9 », « 33500.00 »),
// après avoir retiré les dates ISO (2026-06-22), les numéros de section, et en ignorant les années isolées.
const sansDates = texte
  .replace(/\d{4}-\d{2}-\d{2}/g, " ")
  .replace(/^\s*\d+[.)]\s/gm, " ");
const trouves = [...sansDates.matchAll(/\d[\d   ]*(?:[.,]\d+)?/g)]
  .map(m => Number(m[0].replace(/[\s ]/g, "").replace(",", ".")))
  .filter(n => !Number.isNaN(n) && n >= 1 && !(n >= 2000 && n <= 2100));
const inconnus = [...new Set(trouves)].filter(n => !autorises.has(n));

// Une alerte (semaine vide) ne doit produire AUCUN chiffre : on vérifie la phrase imposée.
const alerte_respectee = !kpi.alerte || texte.trim().startsWith("Rapport non généré");

return [{ json: {
  texte,
  controle_ok: inconnus.length === 0 && alerte_respectee && !kpi.alerte,
  alerte: kpi.alerte,
  chiffres_inconnus: inconnus,
  texte_final: inconnus.length === 0 ? texte
    : texte + `\n\n⚠️ CONTRÔLE AUTOMATIQUE : chiffres non reconnus ${inconnus.join(", ")} — rapport à relire avant diffusion.`
} }];
